def cerca(nodo, x):
    if nodo is None:
        return None
    if nodo.key == x:
        return nodo
    if x < nodo.key:
        return cerca(nodo.left, x)
    return cerca(nodo.right, x)

def profondita(nodo, x):
    if nodo is None:
        return -1
    if nodo.key == x:
        return 0
    if x < nodo.key:
        d = profondita(nodo.left, x)
    else:
        d = profondita(nodo.right, x)
    if d == -1:
        return -1
    return d + 1

def minimo_maggiore_uguale(nodo, x):
    if nodo is None:
        return None
    if nodo.key == x:
        return nodo.key
    if nodo.key < x:
        return minimo_maggiore_uguale(nodo.right, x)
    c = minimo_maggiore_uguale(nodo.left, x)
    if c is None:
        return nodo.key
    return c

