def inserisci(root, x):
    if root is None:
        return NodoABR(x)           # il costruttore pone count = 1
    if x == root.key:
        root.count = root.count + 1
    elif x < root.key:
        root.left = inserisci(root.left, x)
    else:
        root.right = inserisci(root.right, x)
