def inserisci(root, x):
    if root is None:
        return NodoABR(x), True
    if x == root.key:
        return root, False
    if x < root.key:
        root.left, inserito = inserisci(root.left, x)
    else:
        root.right, inserito = inserisci(root.right, x)
    return root, inserito

def minimo(root):
    if root is None:
        return None
    if root.left is None:
        return root.key
    return minimo(root.left)

def massimo(root):
    if root is None:
        return None
    m = root.key
    ms = massimo(root.left)
    md = massimo(root.right)
    if ms is not None and ms > m:
        m = ms
    if md is not None and md > m:
        m = md
    return m

def massimo(root):
    if root is None:
        return None
    if root.right is None:
        return root.key
    return massimo(root.right)

def secondo_massimo(root):
    if root is None:
        return None
    if root.right is None:
        # root contiene il massimo: il secondo e' il massimo del sottoalbero sinistro
        return massimo(root.left)
    if root.right.left is None and root.right.right is None:
        # il figlio destro e' il massimo e non ha figli: il secondo e' root.key
        return root.key
    return secondo_massimo(root.right)

def stampa_decrescente(nodo):
