        stampa_decrescente(nodo.right)
        print(nodo.key)
        stampa_decrescente(nodo.left)

def chiavi_ordinate(nodo, lista):
    if nodo is not None:
        chiavi_ordinate(nodo.left, lista)
        lista.append(nodo.key)
        chiavi_ordinate(nodo.right, lista)
    return lista

def k_esimo(nodo, k):
    return cerca_k(nodo, k)[0]

def cerca_k(nodo, k):
    # restituisce (chiave, k residuo): la chiave e' None se non e' ancora stata trovata
    if nodo is None:
        return None, k
    chiave, k = cerca_k(nodo.left, k)
    if chiave is not None:
        return chiave, k
    k = k - 1
    if k == 0:
        return nodo.key, 0
    return cerca_k(nodo.right, k)

def info(nodo):
    if nodo is None:
        return True, None, None          # l'albero vuoto è un ABR
    ok_s, min_s, max_s = info(nodo.left)
    ok_d, min_d, max_d = info(nodo.right)
    if not ok_s or not ok_d:
        return False, None, None
    if max_s is not None and max_s >= nodo.key:
        return False, None, None
    if min_d is not None and min_d <= nodo.key:
        return False, None, None
    mn = nodo.key if min_s is None else min_s
    mx = nodo.key if max_d is None else max_d
    return True, mn, mx

def is_abr(radice):
    ok, _ = controlla(radice, None)
    return ok

def controlla(nodo, prec):
    # visita in ordine: restituisce (ok, ultima chiave vista)
    if nodo is None:
        return True, prec
    ok, prec = controlla(nodo.left, prec)
    if not ok:
        return False, prec
    if prec is not None and nodo.key <= prec:
        return False, prec
    return controlla(nodo.right, nodo.key)

def verifica(nodo, minimo, massimo):
    # sinistro < chiave <= destro: i duplicati stanno a destra
    if nodo is None:
        return True
    if minimo is not None and nodo.key < minimo:
        return False
    if massimo is not None and nodo.key >= massimo:
        return False
    return verifica(nodo.left, minimo, nodo.key) and verifica(nodo.right, nodo.key, massimo)

def is_abr_dup(radice):
    return verifica(radice, None, None)
